used = set(json.load(open('/tmp/claude-1000/-home-logstar-code-github-funlikely-puchi-shichigo/36e3ca03-cb83-47e7-90a8-d2b456079ce4/scratchpad/used.json')))
out=[]
for i,(th,ws) in enumerate(T.items(),1):
    import tiling as T, lexicon as lx
    def ugly(x):
        g=T.good_tilings(x)
        return not g or sum(lx.ugly_boundaries(t,i==0,i==len(g[0])-1) for i,t in enumerate(g[0]))>0
    w=[x for x in ws.split() if x not in used and 5<=len(x)<=10 and not ugly(x)]
    out.append({"id":f"T{i:02d}","category":"themed","theme":th,"allowProperNouns":False,"words":w[:16]})
    print(th, len(w), [x for x in ws.split() if x in used])
json.dump(out,open('work/manual_sets-005.json','w'),indent=1)
vet=set(open('data/vetted_words.txt').read().split())
new=[w for m in out for w in m['words'] if w not in vet]
open('data/vetted_words.txt','a').write('\n'.join(new)+'\n')
